package com.client.multichatwindows.config.ui; import com.client.multichatwindows.config.*; import com.client.multichatwindows.config.model.*; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.client.gui.screen.Screen; import net.minecraft.client.gui.widget.TextFieldWidget; import net.minecraft.text.Text; public class DependenciesScreen extends ScrollableDarkScreen { private final Screen parent; private final String serverKey; private final int tabIndex; private ServerConfig sc; private TabConfig tab; private int scrollY=0; public DependenciesScreen(Screen parent,String serverKey,int tabIndex){super(Text.translatable("multichatwindows.dependencies.title"));this.parent=parent;this.serverKey=serverKey;this.tabIndex=tabIndex;} @Override protected void init(){clearChildren();sc=ConfigManager.getOrCreateServer(serverKey);tab=(tabIndex>=0&&tabIndex<sc.tabs.size())?sc.tabs.get(tabIndex):null;int cx=width/2;if(tab==null||"all".equalsIgnoreCase(tab.id)){addDrawableChild(new DarkButton(cx-100,height-28,200,20,Text.translatable("multichatwindows.back"),()->MinecraftClient.getInstance().setScreen(parent)));return;}int top=54,bottom=height-110,rowH=24,max=Math.max(0,tab.dependencies.size()*rowH-(bottom-top));scrollY=Math.max(0,Math.min(scrollY,max));int y=top-scrollY;for(int i=0;i<tab.dependencies.size();i++){DependencyRule r=tab.dependencies.get(i);final int idx=i;if(y+20>=top&&y<=bottom){addDrawableChild(new DarkButton(cx-100,y,70,20,Text.translatable(r.player?"multichatwindows.dep.player":"multichatwindows.dep.msg"),()->{r.player=!r.player;ConfigManager.saveServer(serverKey,sc);init();}));TextFieldWidget tf=new TextFieldWidget(textRenderer,cx-25,y,125,20,Text.translatable("multichatwindows.dep.value"));tf.setText(r.value==null?"":r.value);tf.setChangedListener(s->r.value=s);addDrawableChild(tf);addDrawableChild(new DarkButton(cx+104,y,36,20,Text.translatable("multichatwindows.delete"),()->{tab.dependencies.remove(idx);ConfigManager.saveServer(serverKey,sc);init();}));}y+=rowH;}addDrawableChild(new DarkButton(cx-100,height-54,200,20,Text.translatable("multichatwindows.dependencies.add"),()->{tab.dependencies.add(new DependencyRule());ConfigManager.saveServer(serverKey,sc);init();}));addDrawableChild(new DarkButton(cx-100,height-28,200,20,Text.translatable("multichatwindows.back"),()->MinecraftClient.getInstance().setScreen(parent)));} @Override protected boolean onScroll(int delta){if(tab!=null&&!"all".equalsIgnoreCase(tab.id)){scrollY+=delta;init();}return true;} @Override public void render(DrawContext ctx,int mouseX,int mouseY,float delta){super.render(ctx,mouseX,mouseY,delta);ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.dependencies.title"),width/2,14,0xFFFFFFFF);if(tab!=null&&"all".equalsIgnoreCase(tab.id))ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.all_tab.nodeps"),width/2,34,0xFFB0B0B0);else ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.dependencies.hint"),width/2,28,0xFFB0B0B0);} }
